commands=[]
for args in [['git','rev-parse','HEAD'],['git','status','--porcelain=v1','--untracked-files=no']]:
    r=subprocess.run(args,cwd=ROOT,capture_output=True); index=len(commands)
    (OUT/f'git-{index}.stdout').write_bytes(r.stdout); (OUT/f'git-{index}.stderr').write_bytes(r.stderr)
    commands.append(dict(actualargv=args,cwd=str(ROOT),exit=r.returncode,stdout_ref=ref(OUT/f'git-{index}.stdout'),stderr_ref=ref(OUT/f'git-{index}.stderr')))
